const $=id=>document.getElementById(id), video=$('source-video'), canvas=$('selection'), ctx=canvas.getContext('2d');
let file=null,objectURL=null,box=null,anchor=null,available=false,busy=false,loaded=false;const exports=[];
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,6500);}
function tab(name){for(const id of ['studio','projects','guide'])$(id).hidden=id!==name;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));$('crumb').textContent={studio:'Cleanup studio',projects:'My exports',guide:'Quick guide'}[name];}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));$('help').onclick=()=>tab('guide');$('new-project').onclick=()=>{tab('studio');if(busy)return toast('Please wait for the current export to finish.');$('file-input').click();};
async function health(){try{const r=await fetch('/api/health');if(!r.ok)throw Error();const j=await r.json();available=!!j.available;}catch{available=false;}$('engine-status').textContent=available?'● Local engine ready':'○ Editor preview';$('engine-status').style.color=available?'#6c9f88':'#a08bb7';$('engine-offline').hidden=available;$('private-badge')?.removeAttribute('hidden');update();}health();
function update(){$('remove').disabled=!available||!loaded||!box||busy;$('clear').disabled=!box||busy;$('replace').disabled=busy;$('quality').disabled=busy;$('action-hint').textContent=busy?'Keep this window open while processing':!file?'Upload a video to get started':!loaded?'Loading video…':!box?'Select the watermark to continue':!available?'Open the local studio to process':'Your original file stays untouched';$('selection-count').textContent=box?'1 area':'0 areas';$('selection-empty').hidden=!!box;$('selection-info').hidden=!box;if(box)$('selection-info').textContent=`⌖ Watermark · ${Math.round(box.w*video.videoWidth)} × ${Math.round(box.h*video.videoHeight)} px`;$('step-select').classList.toggle('current',loaded);$('step-export').classList.toggle('current',busy);}
function time(s){if(!Number.isFinite(s))return '00:00';return `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;}
function draw(){const r=canvas.getBoundingClientRect();canvas.width=Math.round(r.width*devicePixelRatio);canvas.height=Math.round(r.height*devicePixelRatio);ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);ctx.clearRect(0,0,r.width,r.height);if(!box)return;const x=box.x*r.width,y=box.y*r.height,w=box.w*r.width,h=box.h*r.height;ctx.fillStyle='rgba(155,119,243,.22)';ctx.fillRect(x,y,w,h);ctx.strokeStyle='#c7a4ff';ctx.lineWidth=2;ctx.strokeRect(x,y,w,h);ctx.fillStyle='#fff';for(const [px,py] of [[x,y],[x+w,y],[x,y+h],[x+w,y+h]])ctx.fillRect(px-3,py-3,6,6);}
new ResizeObserver(draw).observe($('video-holder'));
function point(e){const r=canvas.getBoundingClientRect();return {x:Math.min(.998,Math.max(.002,(e.clientX-r.left)/r.width)),y:Math.min(.998,Math.max(.002,(e.clientY-r.top)/r.height))};}
canvas.onpointerdown=e=>{if(!loaded||busy)return;video.pause();anchor=point(e);canvas.setPointerCapture(e.pointerId);$('selection-tip').hidden=true;};
canvas.onpointermove=e=>{if(!anchor)return;const p=point(e);box={x:Math.min(anchor.x,p.x),y:Math.min(anchor.y,p.y),w:Math.abs(p.x-anchor.x),h:Math.abs(p.y-anchor.y)};draw();};
function finish(){if(!anchor)return;anchor=null;if(!box||box.w*video.videoWidth<4||box.h*video.videoHeight<4)box=null;draw();update();}canvas.onpointerup=finish;canvas.onpointercancel=finish;
$('clear').onclick=()=>{box=null;draw();update();$('selection-tip').hidden=false;};
$('browse').onclick=$('replace').onclick=()=>$('file-input').click();$('file-input').onchange=e=>{if(e.target.files[0])load(e.target.files[0]);e.target.value='';};
function load(f){if(busy)return toast('Wait for the current export to finish.');if(f.size>500*1024*1024)return toast('Please choose a video smaller than 500 MB.');if(!f.type.startsWith('video/'))return toast('Please choose a video file.');file=f;loaded=false;box=null;video.pause();if(objectURL)URL.revokeObjectURL(objectURL);objectURL=URL.createObjectURL(f);video.src=objectURL;$('upload-view').hidden=true;$('video-holder').hidden=false;$('replace').hidden=false;$('file-tag').textContent=f.name;$('file-tag').title=f.name;$('result').hidden=true;$('progress-wrap').hidden=true;$('selection-tip').hidden=false;$('resolution').textContent='Reading…';update();}
video.onloadedmetadata=()=>{if(!Number.isFinite(video.duration)||!video.videoWidth){toast('This video cannot be read. Try an MP4 with H.264 video.');return;}loaded=true;$('duration').textContent=time(video.duration);$('resolution').textContent=`${video.videoWidth} × ${video.videoHeight}`;$('play').disabled=$('seek').disabled=$('fullscreen').disabled=false;draw();update();};video.onerror=()=>{loaded=false;update();toast('Your browser cannot play this video. Try an H.264 MP4.');};video.ontimeupdate=()=>{$('current-time').textContent=time(video.currentTime);$('seek').value=video.duration?video.currentTime/video.duration*100:0;};video.onplay=()=>$('play').textContent='Ⅱ';video.onpause=()=>$('play').textContent='▶';$('play').onclick=()=>video.paused?video.play().catch(()=>toast('Playback unavailable.')):video.pause();$('seek').oninput=e=>video.currentTime=Number(e.target.value)*video.duration/100;$('fullscreen').onclick=()=>video.requestFullscreen?.();
const zone=$('drop-zone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragging');};zone.ondragleave=()=>zone.classList.remove('dragging');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragging');if(e.dataTransfer.files[0])load(e.dataTransfer.files[0]);};
$('remove').onclick=async()=>{if(!file||!box||busy||!available)return;busy=true;video.pause();update();$('result').hidden=true;$('progress-wrap').hidden=false;$('progress-bar').style.width='0%';$('progress-label').textContent='Uploading to local engine…';try{const r=await fetch(`/api/jobs?box=${encodeURIComponent(JSON.stringify(box))}&quality=${$('quality').value}`,{method:'POST',headers:{'Content-Type':file.type},body:file});const j=await r.json();if(!r.ok)throw Error(j.error||'Upload failed.');let misses=0;while(true){await new Promise(resolve=>setTimeout(resolve,900));let status;try{const response=await fetch(`/api/jobs/${j.id}`);status=await response.json();if(!response.ok)throw Error(status.error);misses=0;}catch(e){if(++misses<4)continue;throw e;}$('progress-bar').style.width=`${status.progress||0}%`;$('progress-label').textContent=status.status==='inspecting'?'Inspecting video…':`Repairing and encoding · ${status.progress||0}%`;if(status.status==='failed')throw Error(status.error||'Repair failed.');if(status.status==='completed'){const url=`/outputs/${j.id}.mp4`;$('result-video').src=url;$('download').href=url;$('result').hidden=false;$('progress-label').textContent='Export complete';exports.unshift({name:file.name,url});renderExports();$('result').scrollIntoView({behavior:'smooth',block:'center'});toast('Your repaired video is ready to review.');break;}}}catch(e){$('progress-label').textContent='Export could not complete';toast(e.message);}finally{busy=false;update();}};
function renderExports(){$('export-count').textContent=exports.length;const list=$('exports-list');list.replaceChildren();for(const item of exports){const row=document.createElement('div');row.className='export-row';const name=document.createElement('span');name.textContent=item.name;const a=document.createElement('a');a.className='primary';a.textContent='↓ Download';a.href=item.url;a.download='clearframe-cleaned.mp4';row.append(name,a);list.append(row);}}
